(() => {
  const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const safeURL=s=>{try{const u=new URL(s);return u.protocol==='https:'?u.href:''}catch{return ''}};
  const rich=s=>escape(s).replace(/\[([^\]]{1,160})\]\((https:\/\/[^\s)]+)\)/g,(_,label,url)=>{const href=safeURL(url.replace(/&amp;/g,'&'));return href?`<a href="${escape(href)}" target="_blank" rel="noopener">${label} ↗</a>`:label}).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\n/g,'<br>');
  const panel=document.createElement('dialog');panel.className='companion';panel.id='companion';panel.setAttribute('aria-labelledby','companion-title');
  panel.innerHTML=`<header><div><span class="eyebrow">GUANWU · YOUR COMPANION</span><h2 id="companion-title">有好奇，随时问。</h2></div><button class="companion-close" aria-label="关闭伴游">×</button></header><div class="companion-context"></div><div class="companion-status" role="status">正在检查连接…</div><div class="companion-messages" role="log" aria-live="polite"><div class="companion-welcome"><span>✧</span><h3>让眼前的文物，多讲一点。</h3><p>我会先查观物的资料，再陪你看细节、听故事、安排一次从容的参观。</p></div></div><div class="companion-suggestions"><button data-prompt="这件文物有哪些值得细看的地方？请附来源。">找一个细节</button><button data-prompt="请给8岁孩子讲讲当前文物或场馆，用简短、易懂的话。">讲给孩子听</button><button data-prompt="我只有45分钟，请围绕当前场馆安排参观，留出休息时间。">只有45分钟</button><button data-prompt="请建议将当前场馆加入我的行程。">规划下一站</button></div><form class="companion-form"><label class="sr-only" for="companion-input">你的参观问题</label><textarea id="companion-input" rows="2" maxlength="1500" placeholder="眼前的文物，让你想到了什么？"></textarea><button class="solid-btn companion-send" type="submit">发送 ↑</button><button class="outline-btn companion-stop" type="button" hidden>停止</button></form><footer>DeepSeek · 基于资料的 AI 讲解，重要信息请对照展签与馆方。<button class="companion-reset">开始新对话</button></footer>`;
  document.body.append(panel);
  const launcher=document.createElement('button');launcher.className='companion-launcher';launcher.dataset.companion='';launcher.innerHTML='<span>✧</span> 随行伴游';launcher.setAttribute('aria-label','打开 AI 随行伴游');document.body.append(launcher);
  const q=s=>panel.querySelector(s),messages=q('.companion-messages'),form=q('form'),input=q('textarea');
  let history=[],controller=null,ready=false;
  function context(){const custom=window.GuanwuExperience?.context();if(custom)return custom;const [kind,id]=(location.hash.slice(1)||'discover').split('/');const ms=[...GUANWU.museums,...GUANWU_EXPANSION.museums,...GUANWU_CITY_MUSEUMS.museums],all=[...ms,...GUANWU.crafts,...GUANWU_EXPANSION.artifacts];const item=all.find(x=>x.id===id);return {id:item?.id||'',name:item?.name||item?.title||'选择一座场馆或一件文物，让讲解更贴近此刻。',museum:kind==='museum'?id:item?.museum||''}}
  function updateContext(){const c=context();q('.companion-context').innerHTML=`<span>正在看</span><strong>${escape(c.name)}</strong>`}
  async function check(){const status=q('.companion-status');try{const r=await fetch('/api/guide/status',{cache:'no-store'});if(!r.ok)throw Error();const data=await r.json();ready=data.configured===true;status.textContent=ready?'● DeepSeek 已连接 · 先查资料，再回答':'DeepSeek 尚未配置，暂不能生成 AI 讲解。';status.classList.toggle('connected',ready)}catch{status.textContent='当前环境未提供伴游服务，请在正式服务或本机预览中打开。';ready=false}q('.companion-send').disabled=!ready}
  async function open(){updateContext();if(!panel.open)panel.showModal();await check();input.focus()}
  function append(role,text){const node=document.createElement('article');node.className='companion-message '+role;node.innerHTML=`<small>${role==='user'?'你':'观物伴游'}</small><div>${rich(text)}</div>`;messages.append(node);messages.scrollTop=messages.scrollHeight;return node}
  function busy(value){q('.companion-send').hidden=value;q('.companion-stop').hidden=!value;input.disabled=value;panel.setAttribute('aria-busy',String(value));q('.companion-suggestions').querySelectorAll('button').forEach(b=>b.disabled=value)}
  async function send(message){if(controller||!message.trim())return;if(!ready){check();return}const c=context();append('user',message);input.value='';const pending=append('assistant','正在查阅资料，组织讲解…');controller=new AbortController();busy(true);try{const r=await fetch('/api/guide',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message,history,context:c.id}),signal:controller.signal});const data=await r.json();if(!r.ok)throw Error(data.error||'讲解暂时不可用');pending.querySelector('div').innerHTML=rich(data.answer);if(data.references?.length){const refs=document.createElement('div');refs.className='companion-references';refs.innerHTML=data.references.filter(x=>safeURL(x.url)).map(x=>`<a href="${escape(safeURL(x.url))}" target="_blank" rel="noopener">${escape(x.title)} ↗</a>`).join('');pending.append(refs)}for(const p of data.proposals||[]){if(p.type!=='add_museum'||![...GUANWU.museums,...GUANWU_EXPANSION.museums,...GUANWU_CITY_MUSEUMS.museums].some(m=>m.id===p.id))continue;const button=document.createElement('button');button.className='outline-btn';button.textContent='确认'+p.label;button.onclick=()=>{const key='guanwu-plan-v2';let plan;try{plan=JSON.parse(localStorage.getItem(key)||'[]')}catch{plan=[]}if(!Array.isArray(plan))plan=[];if(!plan.includes(p.id))plan.push(p.id);localStorage.setItem(key,JSON.stringify(plan));state.plan=plan;render(false);button.textContent='✓ 已加入我的行程';button.disabled=true};pending.append(button)}history.push({role:'user',content:message},{role:'assistant',content:data.answer});history=history.slice(-8)}catch(error){pending.querySelector('div').textContent=error.name==='AbortError'?'已停止本次讲解。':error.message;const retry=document.createElement('button');retry.className='text-link';retry.textContent='重新提问 →';retry.onclick=()=>send(message);pending.append(retry)}finally{controller=null;busy(false);messages.scrollTop=messages.scrollHeight;input.focus()}}
  form.onsubmit=e=>{e.preventDefault();send(input.value.trim())};q('.companion-stop').onclick=()=>controller?.abort();q('.companion-close').onclick=()=>panel.close();q('.companion-reset').onclick=()=>{controller?.abort();history=[];messages.innerHTML='<div class="companion-welcome"><span>✧</span><h3>新的一次相遇。</h3><p>带着眼前的问题，从一件文物开始。</p></div>'};q('.companion-suggestions').onclick=e=>{if(e.target.dataset.prompt)send(e.target.dataset.prompt)};
  document.addEventListener('guanwu:ask',async e=>{await open();if(e.detail?.prompt)send(e.detail.prompt)});
  document.addEventListener('click',e=>{if(e.target.closest('[data-companion]'))open()});window.addEventListener('hashchange',updateContext);
  input.addEventListener('keydown',e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();form.requestSubmit()}});
})();
